import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Helper to replace InstancedMesh with individual Meshes
// This ensures OBJExporter handles them correctly as distinct geometries/positions
function replaceInstancedMeshes(object) {
    const replacements = [];
    object.traverse((child) => {
        if (child.isInstancedMesh) {
            replacements.push(child);
        }
    });

    replacements.forEach((instancedMesh) => {
        const parent = instancedMesh.parent;
        if (!parent) return;

        const geometry = instancedMesh.geometry;
        const material = instancedMesh.material;
        const count = instancedMesh.count;

        for (let i = 0; i < count; i++) {
            const matrix = new THREE.Matrix4();
            instancedMesh.getMatrixAt(i, matrix);

            const mesh = new THREE.Mesh(geometry, material);
            mesh.applyMatrix4(matrix);
            mesh.name = `${instancedMesh.name}_${i}`;

            parent.add(mesh);
        }
        parent.remove(instancedMesh);
    });
}

// 1. Create the scene
const scene = createScene();

// 2. Expand InstancedMesh to Meshes
replaceInstancedMeshes(scene);

// 3. Create a wrapper to hold the rotated scene
// We do this so the OBJExporter traverses this wrapper and applies the transform to the children (effectively baking it)
// or we can bake it manually.
// The safest way with OBJExporter to ensure "world" coordinates are written is to parse the object 
// but we want the "world" to be the rotated one.

const wrapper = new THREE.Group();
wrapper.name = 'ExportWrapper';
wrapper.add(scene);

// 4. Apply the requested rotation: -90 degrees on X
scene.rotation.x = -Math.PI / 2;

// 5. Update the world matrix of the entire hierarchy
wrapper.updateMatrixWorld(true);

// 6. Export
const exporter = new OBJExporter();
// We parse the wrapper. The exporter should respect the hierarchy transforms.
const result = exporter.parse(wrapper);

// 7. Write to file
const outputPath = path.resolve('./output/object.obj');
fs.writeFileSync(outputPath, result);

console.log(`Exported object to ${outputPath} with rotation applied.`);
